221	// ── Optional SOURCE read-only enforcement (opt-in via env) ──────────────────
222	// The engine only ever READS from a source (detection probes, rsync PULL, DB
223	// dump). These flags turn that from convention into ENFORCEMENT — used by the
224	// rehearsal harness so a source can never be written to. Default OFF, so normal
225	// customer migrations are completely unaffected.
226	const SRC_READONLY = process.env.MIGRATE_SOURCE_READONLY === "1";
227	const SRC_AUDIT = SRC_READONLY || process.env.MIGRATE_SOURCE_AUDIT === "1";
228	// OPT-IN: when a compose project pins a `container_name:` already claimed by an
229	// earlier project (the classic prod + its staging clone that hardcode the same
230	// names), the DEFAULT is to skip the clone. With this flag set, the clone is
231	// instead brought up under namespaced container names + its own compose project.
232	// OFF by default, so normal migrations are completely unaffected.
233	const RENAME_CLONE_CONTAINERS = process.env.MIGRATE_RENAME_CLONE_CONTAINERS === "1";
234	// CATASTROPHIC, unambiguous write/destroy commands only, anchored to command
235	// position (start-of-line or after a newline / pipe / ; / & / backtick) so a
236	// matching word inside a filename or a read like `cat /etc/passwd` is NOT flagged.
237	// Deliberately narrow: read-only detection scripts legitimately use redirects
238	// (`2>&1`, `>/dev/null`), `systemctl`/`service` strings, `sed`, etc., so blocking
239	// those caused false positives that broke the engine. `dd` is only flagged when it
240	// writes to a real disk device. Everything is still AUDITED regardless.
241	const SRC_WRITE_RE = /(?:^|[\n|;&`]\s*)(?:rm|rmdir|mv|shred|mkfs\S*|mkswap|parted|fdisk|chmod|chown|useradd|userdel|passwd|shutdown|reboot|halt|poweroff|init\s+[06])\b|(?:^|[\n|;&`]\s*)dd\s[^\n|;&`]*\bof=\/dev\/(?:sd|nvme|vd|xvd|hd|mapper)/i;
242	function auditSource(cmd: string): void {
243	  if (!SRC_AUDIT) return;
244	  try { appendFileSync("/opt/nxeon/migration-source-audit.log", `${new Date().toISOString()} ${cmd.replace(/\s+/g, " ").slice(0, 800)}\n`); } catch { /* best effort */ }
245	}
246	function assertSourceReadOnly(cmd: string): void {
247	  if (SRC_READONLY && SRC_WRITE_RE.test(cmd)) {
248	    throw new Error(`source read-only guard refused a possible WRITE command: ${cmd.replace(/\s+/g, " ").slice(0, 140)}`);
249	  }

